 rubric=[('Honesty', 'Disclosure on every link', 'Clear policy page'), ('Content', 'Three helpful pieces', 'Readers say it helped'), ('Product choice', 'Evidence for ten items', 'Rejected items explained'), ('Tracking', 'Four weeks complete', 'Changes from data'), ('Review', 'Time and money counted', 'Plan improves results')],
