_ex = ['A reader wants a pan for eggs. Your page compares three pans, 24 cm, with a test of 10 eggs each: pan A stuck twice, pan B once, pan C never. You link pan C and say pan A is cheaper but sticks.', "Niche test: 'budget camping gear' is too wide; 'first-time family camping, under 150 total' names the reader, the budget and the problem. Amounts are in your currency.", 'You tested a kettle for 4 weeks, noting boil time (3 min 10 s), noise and a cracked lid in week 3. The honest review lists the lid fault even though the commission is 8%.', 'Your page ranks four toasters in a table with price, slots, test result and who it suits; readers can pick without clicking any link.', "The first line reads: 'I earn a small commission if you buy through links on this page, at no extra cost to you.' Every link sits within three lines of a repeat notice.", "A short video answering 'which pan for eggs?' brings 120 visits in a week; a keyword-stuffed page brings 9.", '400 clicks give 12 orders (3%) and 48 in commission, so earnings per click are 0.12. Pages under 0.05 are rewritten or removed.', 'You spent 20 hours for 48 earned, 2.40 an hour. The plan: improve the two best pages before writing any new ones. Amounts are in your currency.']
_extra = ['Write down what you would pay for yourself; start with products you already know.', "Read the terms for banned claims such as 'cure' or 'guaranteed'.", 'Use a spreadsheet to compare three programmes on rate, window, threshold and payment date.', 'Keep a list of products you tested and the dates, so claims can be proved.', 'Set a rule: no product is listed without at least one real use or a documented second source.', 'Keep sponsored and affiliate content labelled differently so readers can tell them apart.', 'Re-check links monthly; dead links lose trust and income.', 'Disclose changes of programme in a short note when you move links.', 'Offer a free checklist for readers who sign up with consent, instead of pushing sales.', 'Respond to every comment within two days, including criticism.', 'Use clear photos from your own testing rather than stock pictures.', 'Track clicks by page so you know which advice is read.', 'Delete pages that no one reads after three months.', 'Share one lesson from each month in your own words.', "Write the next month's plan with three pages to improve and one to build.", 'Ask two readers if the disclosure and the advice felt fair, and apply their comments.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['Remember that you earn a commission only when a reader buys through your link, so a small trusted audience can outperform a large indifferent one.', "Read each programme's terms for tracking-cookie length, payment threshold and banned methods before you join, and keep a copy of the terms."], ['Choose a niche you could write about across 50 articles, check that people search for it, and confirm that related products pay a reasonable commission.', 'Test the idea by listing twenty questions buyers ask in this niche; if you cannot find twenty, the niche may be too narrow.'], ['Recommend only products you have tried or researched thoroughly, and compare at least three alternatives so your advice is fair to the reader.', "Check each seller's refund rate, support quality and reputation, and drop partners who pay late or are hard to contact."], ['Write guides that each answer one clear question, with a short summary at the top, honest pros and cons, and a plain recommendation.', 'Update each article every six months to check prices, links and facts, and show the update date so readers know it is current.'], ['Place a statement in plain words near each link saying you may earn a commission, visible before the reader clicks rather than buried in a footer.', 'Never claim results you have not seen, never write fake reviews, and follow the advertising rules of your country and of each platform you use.'], ['Build traffic with useful articles, an email list and honest social posts, aiming for steady growth such as 10 percent more visitors each month.', 'Avoid spam, hidden links and paid fake engagement, since these can get your account banned and destroy trust that took months to earn.'], ['Use a unique tracking link for each article, record clicks, sales and earnings in a spreadsheet, and then work out your earnings per click.', 'Calculate profit by subtracting hosting, tools and advertising costs from commission earned, and choose the three articles that deserve more effort next month.'], ['Every quarter, review your best and worst pages, retire the weak ones, and set a target such as two new guides and one update each month.', 'Write a one-page plan with goals, schedule and budget, and review it with a trusted friend who will tell you honestly which parts are unclear.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {"7": "Out of 250 clicks, 5 became orders (2%) and paid 30; that is 0.12 a click. The post earning 0.02 a click is rewritten. Amounts are in your currency.", "8": "12 hours for 36 earned is 3 an hour; the plan is to update the two posts that bring most clicks before writing a new one. Amounts are in your currency."}
C['deep']['mods'] = [(m[0], _dupfix.get(str(i + 1), m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will be able to explain how commission links work and judge programme terms before joining, protecting your time and reputation.', 'You will be able to test whether a niche has enough buyer questions and fair-paying products to sustain fifty articles.', 'You will be able to compare alternatives honestly and drop partners with poor refunds, weak support or late payments.', 'You will be able to write single-question guides with a summary, balanced pros and cons, and dated updates readers can trust.', 'You will be able to place plain-language disclosures near every link and avoid claims or fake reviews that break advertising rules.', 'You will be able to grow readership through useful articles and an email list, while avoiding tricks that risk account bans.', 'You will be able to track clicks and sales per article and calculate real profit after hosting, tools and advertising costs.', 'You will be able to review page performance each quarter and decide, with a written plan, whether to continue, adjust or stop.']
